values
  ('6285abed-1753-4d48-8c86-c017d4a79fa2', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Integral Foundations and Strategy', 'Calculus II begins by consolidating the definite integral, the Fundamental Theorem of Calculus, and substitution. The deeper goal is to diagnose an integrand, choose a defensible method, and verify the result rather than memorize disconnected tricks.', 0),
  ('70afc91c-1f72-435e-b889-c3d17de132b3', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '6285abed-1753-4d48-8c86-c017d4a79fa2', 'subtopic'::public.curated_course_node_type, 'Fundamental Theorem and net change review', 'The Fundamental Theorem remains the conceptual anchor: integrals accumulate and antiderivatives evaluate that accumulation.', 0),
  ('050d5240-93f5-4775-9df7-5c10fc4d8bc1', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '70afc91c-1f72-435e-b889-c3d17de132b3', 'concept'::public.curated_course_node_type, 'Accumulation functions and both parts of the Fundamental Theorem', null, 0),
  ('2a69dcab-0473-4ea0-a9b3-17445bc7a2a2', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '70afc91c-1f72-435e-b889-c3d17de132b3', 'concept'::public.curated_course_node_type, 'Net change, signed accumulation, and total accumulation', null, 1),
  ('53955343-1273-4acc-b128-705ab274fd6b', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '70afc91c-1f72-435e-b889-c3d17de132b3', 'concept'::public.curated_course_node_type, 'Average value and units of a definite integral', null, 2),
  ('609e74c8-4d6c-4652-9708-fbff9579cdee', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '70afc91c-1f72-435e-b889-c3d17de132b3', 'concept'::public.curated_course_node_type, 'Differentiating integrals with variable limits', null, 3),
  ('78046b37-a381-4b83-9c3f-46c4975ed347', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '6285abed-1753-4d48-8c86-c017d4a79fa2', 'subtopic'::public.curated_course_node_type, 'Substitution and inverse chain-rule structure', 'Substitution succeeds when the integrand contains a composite function together with the differential pattern of its inner function.', 1),
  ('5c191a19-be73-4407-ad3e-2c17e3dd29fe', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '78046b37-a381-4b83-9c3f-46c4975ed347', 'concept'::public.curated_course_node_type, 'Indefinite substitution and back-substitution', null, 0),
  ('66b359a0-77f3-4728-858a-e4aee6dfb2a9', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '78046b37-a381-4b83-9c3f-46c4975ed347', 'concept'::public.curated_course_node_type, 'Definite substitution with transformed bounds', null, 1),
  ('c58852f9-413f-45a3-873e-9ad9114a2dff', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '78046b37-a381-4b83-9c3f-46c4975ed347', 'concept'::public.curated_course_node_type, 'Algebraic, trigonometric, exponential, and logarithmic patterns', null, 2),
  ('4b5780eb-3b09-4093-9df5-ec3bb97c78c7', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '78046b37-a381-4b83-9c3f-46c4975ed347', 'concept'::public.curated_course_node_type, 'Checking an antiderivative by differentiation', null, 3),
  ('cb76bb0a-4255-414a-a427-f279401a5ddf', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '6285abed-1753-4d48-8c86-c017d4a79fa2', 'subtopic'::public.curated_course_node_type, 'Integration strategy', 'A good integrator first simplifies and classifies the expression, then selects the least complicated method that matches its structure.', 2),
  ('7eb49ecb-9574-496e-b5b6-f3ab12b97f22', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'cb76bb0a-4255-414a-a427-f279401a5ddf', 'concept'::public.curated_course_node_type, 'Algebraic division, factoring, identities, and completing the square', null, 0),
  ('8425ee19-a4c5-42ca-9396-d60622fac4a0', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'cb76bb0a-4255-414a-a427-f279401a5ddf', 'concept'::public.curated_course_node_type, 'Recognizing substitution, parts, trigonometric, and rational-function structures', null, 1),
  ('656a3fba-179e-4257-8e21-8861685c7ba4', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'cb76bb0a-4255-414a-a427-f279401a5ddf', 'concept'::public.curated_course_node_type, 'Combining methods in a planned sequence', null, 2),
  ('372b50fd-4d85-4982-868c-328b6126cf3b', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'cb76bb0a-4255-414a-a427-f279401a5ddf', 'concept'::public.curated_course_node_type, 'Explaining why a chosen method fits and why alternatives do not', null, 3),
  ('f8e168a7-fe08-432c-89d0-38fd898205df', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Integration by Parts and Reduction Ideas', 'Integration by parts reverses the product rule. It is essential for products, logarithms, inverse trigonometric functions, and recurring integral families, and it introduces the idea of transforming a problem into a simpler one.', 1),
  ('a9cfbf5b-270f-40d2-9a2a-17807098ada2', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'f8e168a7-fe08-432c-89d0-38fd898205df', 'subtopic'::public.curated_course_node_type, 'Deriving and applying integration by parts', 'The formula is most useful when one factor becomes simpler when differentiated and the other remains integrable.', 0),
  ('0ffde85b-b41d-4a1d-9aeb-198913c93eee', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'a9cfbf5b-270f-40d2-9a2a-17807098ada2', 'concept'::public.curated_course_node_type, 'Derivation from the product rule', null, 0),
  ('d3b8738d-c5c5-4a8e-bc72-734927d143a7', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'a9cfbf5b-270f-40d2-9a2a-17807098ada2', 'concept'::public.curated_course_node_type, 'Choosing u and dv using structural judgment rather than a rigid mnemonic', null, 1),
  ('cd108a60-c59d-49b5-bcb3-4e34694450d6', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'a9cfbf5b-270f-40d2-9a2a-17807098ada2', 'concept'::public.curated_course_node_type, 'Definite and indefinite integrals', null, 2),
  ('212a9990-b43b-4b7d-a95d-451c5e593729', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'a9cfbf5b-270f-40d2-9a2a-17807098ada2', 'concept'::public.curated_course_node_type, 'Repeated integration by parts and tabular organization', null, 3),
  ('77f67f65-37f1-4666-83e2-c7033fac725a', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'f8e168a7-fe08-432c-89d0-38fd898205df', 'subtopic'::public.curated_course_node_type, 'Products and special functions', 'Many common antiderivatives become accessible only after treating one factor as an implicit product with 1.', 1),
  ('dc0c5e19-6503-4ed1-b27c-367ce7107c5c', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '77f67f65-37f1-4666-83e2-c7033fac725a', 'concept'::public.curated_course_node_type, 'Polynomial times exponential or trigonometric functions', null, 0),
  ('b932de83-3516-45a6-ab42-0b43e632f222', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '77f67f65-37f1-4666-83e2-c7033fac725a', 'concept'::public.curated_course_node_type, 'Logarithmic and inverse trigonometric integrals', null, 1),
  ('62c09c0b-c6c9-404d-b511-7e4d77e12c8f', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '77f67f65-37f1-4666-83e2-c7033fac725a', 'concept'::public.curated_course_node_type, 'Exponential-trigonometric cycles', null, 2),
  ('b2e54355-84a7-4c61-a746-2e4760b65781', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '77f67f65-37f1-4666-83e2-c7033fac725a', 'concept'::public.curated_course_node_type, 'Verification and constants of integration', null, 3),
  ('97941b69-9b99-4897-aab2-b6c9fa559d4a', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'f8e168a7-fe08-432c-89d0-38fd898205df', 'subtopic'::public.curated_course_node_type, 'Reduction and recursive relationships', 'A reduction formula expresses a difficult integral in terms of a related, simpler case and reveals patterns useful in computation and analysis.', 2),
  ('42380248-f7bf-4029-a19a-87da6217e701', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '97941b69-9b99-4897-aab2-b6c9fa559d4a', 'concept'::public.curated_course_node_type, 'Deriving a simple reduction formula', null, 0),
  ('60db17ad-635a-4ce7-b441-379537093fa0', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '97941b69-9b99-4897-aab2-b6c9fa559d4a', 'concept'::public.curated_course_node_type, 'Base cases and recursive evaluation', null, 1),
  ('cdceb160-496d-463f-98a5-985e4534aa6a', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '97941b69-9b99-4897-aab2-b6c9fa559d4a', 'concept'::public.curated_course_node_type, 'Recognizing when recursion terminates', null, 2),
  ('5c2f687d-18b0-475a-98a3-77644fcac121', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '97941b69-9b99-4897-aab2-b6c9fa559d4a', 'concept'::public.curated_course_node_type, 'Optional computational implementation of a reduction rule', null, 3),
  ('2c661745-0eb3-4e6e-a73b-ec12a3c53fde', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Trigonometric Integrals and Trigonometric Substitution', 'Trigonometric identities and substitutions turn powers and radical expressions into integrable forms. The point is not identity collection; it is matching algebraic geometry to a useful parameterization.', 2),
  ('c674c604-6d3e-4789-806a-3139069e455e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2c661745-0eb3-4e6e-a73b-ec12a3c53fde', 'subtopic'::public.curated_course_node_type, 'Powers and products of sine and cosine', 'Parity determines which identity or factorization exposes a substitution.', 0),
  ('d61198af-06fe-46ba-a4fc-f61e18212efd', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'c674c604-6d3e-4789-806a-3139069e455e', 'concept'::public.curated_course_node_type, 'Odd powers and saving one factor', null, 0),
  ('8fa8d869-4f48-4efe-95aa-67256376e320', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'c674c604-6d3e-4789-806a-3139069e455e', 'concept'::public.curated_course_node_type, 'Even powers and half-angle identities', null, 1),
  ('a86d1fd6-dd78-4900-b3b8-ab5c921b2c62', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'c674c604-6d3e-4789-806a-3139069e455e', 'concept'::public.curated_course_node_type, 'Mixed sine-cosine products', null, 2),
  ('7accd8ba-e16c-47e2-9a15-3ec3065401c9', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'c674c604-6d3e-4789-806a-3139069e455e', 'concept'::public.curated_course_node_type, 'Definite integrals and symmetry checks', null, 3),
  ('e329a57b-e649-4bcd-9004-997d3deca575', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2c661745-0eb3-4e6e-a73b-ec12a3c53fde', 'subtopic'::public.curated_course_node_type, 'Powers of tangent and secant', 'Tangent-secant integrals use derivative pairings and Pythagorean identities that differ from sine-cosine cases.', 1),
  ('c187df11-b814-40f1-80a4-6f0f4b95b73b', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e329a57b-e649-4bcd-9004-997d3deca575', 'concept'::public.curated_course_node_type, 'Even secant powers and reserving secant-squared', null, 0),
  ('aba01be9-6a42-40e5-8bdb-dc00314fdf12', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e329a57b-e649-4bcd-9004-997d3deca575', 'concept'::public.curated_course_node_type, 'Odd tangent powers and reserving secant-tangent', null, 1),
  ('2be49924-bf63-47fe-a739-293d459fc56e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e329a57b-e649-4bcd-9004-997d3deca575', 'concept'::public.curated_course_node_type, 'Using tan^2(x)+1=sec^2(x)', null, 2),
  ('8fef55e1-4dd0-49f7-ac73-309ffbd6fb25', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e329a57b-e649-4bcd-9004-997d3deca575', 'concept'::public.curated_course_node_type, 'Other trigonometric products as enrichment', null, 3),
  ('971d6b9b-fb28-4546-98c3-5f7b6137fe34', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2c661745-0eb3-4e6e-a73b-ec12a3c53fde', 'subtopic'::public.curated_course_node_type, 'Trigonometric substitution for radicals', 'A substitution based on a right-triangle identity removes square roots associated with circles and hyperbolas.', 2),
  ('a4c43fca-38d3-4b90-a19f-c60f504fa318', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '971d6b9b-fb28-4546-98c3-5f7b6137fe34', 'concept'::public.curated_course_node_type, 'Patterns involving a^2-x^2, a^2+x^2, and x^2-a^2', null, 0),
  ('2c30329a-09ab-4786-ba51-d892cf4828d1', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '971d6b9b-fb28-4546-98c3-5f7b6137fe34', 'concept'::public.curated_course_node_type, 'Choosing sine, tangent, or secant substitutions', null, 1),
  ('e076312c-9132-4996-afe2-50e17ec33965', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '971d6b9b-fb28-4546-98c3-5f7b6137fe34', 'concept'::public.curated_course_node_type, 'Reference triangles and back-substitution', null, 2),
  ('021729b5-e1f4-410c-84fe-91dd5162f396', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '971d6b9b-fb28-4546-98c3-5f7b6137fe34', 'concept'::public.curated_course_node_type, 'Domain, sign, and absolute-value considerations', null, 3),
  ('e5975847-f17c-4616-8f2b-9f1f0d5a828a', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Rational Functions and Partial Fractions', 'Partial fractions decomposes a complicated rational function into standard pieces. It is a systematic algebraic algorithm with applications in differential equations, systems, transforms, and economic dynamics.', 3),
  ('36885f54-66e9-48f4-aeab-eff18430f0f8', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e5975847-f17c-4616-8f2b-9f1f0d5a828a', 'subtopic'::public.curated_course_node_type, 'Preparation and decomposition', 'The method applies to proper rational functions after division and factorization of the denominator.', 0),
  ('7cbd2366-2c73-4d99-89ef-a7bcba7d2329', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '36885f54-66e9-48f4-aeab-eff18430f0f8', 'concept'::public.curated_course_node_type, 'Polynomial long division for improper rational functions', null, 0),
  ('91be8b7b-e806-435e-bfed-fc23219b9250', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '36885f54-66e9-48f4-aeab-eff18430f0f8', 'concept'::public.curated_course_node_type, 'Factoring over the real numbers', null, 1),
  ('9f8d288f-80b2-456c-ba3c-cab906d398db', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '36885f54-66e9-48f4-aeab-eff18430f0f8', 'concept'::public.curated_course_node_type, 'Distinct and repeated linear factors', null, 2),
  ('603f70ee-a4a8-4a02-aea8-d708d20862ff', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '36885f54-66e9-48f4-aeab-eff18430f0f8', 'concept'::public.curated_course_node_type, 'Irreducible quadratic factors and repeated quadratics', null, 3),
  ('cc12b916-9dec-42e5-87a1-9702cbf98ce2', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e5975847-f17c-4616-8f2b-9f1f0d5a828a', 'subtopic'::public.curated_course_node_type, 'Finding coefficients', 'Coefficients can be found by equating polynomials, strategic substitution, or efficient cover-up in appropriate linear cases.', 1),
  ('b3b14f4e-10fd-4aac-be02-b95db65c8997', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'cc12b916-9dec-42e5-87a1-9702cbf98ce2', 'concept'::public.curated_course_node_type, 'Coefficient comparison', null, 0),
  ('8219f778-90d0-439f-9210-366dbb313327', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'cc12b916-9dec-42e5-87a1-9702cbf98ce2', 'concept'::public.curated_course_node_type, 'Strategic values and linear-factor cover-up', null, 1),
  ('3418013f-2b82-44ee-95f5-241575da595e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'cc12b916-9dec-42e5-87a1-9702cbf98ce2', 'concept'::public.curated_course_node_type, 'Systems of equations for repeated or quadratic factors', null, 2),
  ('84215be6-0385-4c3c-959b-753405913fab', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'cc12b916-9dec-42e5-87a1-9702cbf98ce2', 'concept'::public.curated_course_node_type, 'Recombining fractions to verify the decomposition', null, 3),
  ('2980daae-4b8f-4d82-a5e3-6563de0b6caf', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e5975847-f17c-4616-8f2b-9f1f0d5a828a', 'subtopic'::public.curated_course_node_type, 'Integrating decomposed terms', 'Each component maps to a small library of logarithmic, power, or arctangent antiderivatives.', 2),
  ('aa722690-f17e-4f9c-9839-c7f4fec502fd', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2980daae-4b8f-4d82-a5e3-6563de0b6caf', 'concept'::public.curated_course_node_type, 'Logarithmic terms from linear denominators', null, 0),
  ('8c668323-df32-478f-b7a1-ba9ec8b520d3', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2980daae-4b8f-4d82-a5e3-6563de0b6caf', 'concept'::public.curated_course_node_type, 'Powers from repeated linear factors', null, 1),
  ('02760c65-1713-4583-b295-046a6b1a0b00', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2980daae-4b8f-4d82-a5e3-6563de0b6caf', 'concept'::public.curated_course_node_type, 'Completing the square for quadratic terms', null, 2),
  ('e3e925f0-c260-4bfa-adcb-a6571f4a5e31', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2980daae-4b8f-4d82-a5e3-6563de0b6caf', 'concept'::public.curated_course_node_type, 'Combining partial fractions with substitution or other methods', null, 3),
  ('f6c87778-1292-4836-9625-49b8f156bebe', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Numerical Integration and Approximation Error', 'Exact antiderivatives may be unavailable or unnecessary when data are sampled. Numerical integration converts finite function values into reliable approximations and makes error a first-class part of the answer.', 4),
  ('b0c1dfc8-eb0c-45c3-a4d8-5012e1e8c995', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'f6c87778-1292-4836-9625-49b8f156bebe', 'subtopic'::public.curated_course_node_type, 'Quadrature rules', 'Each rule replaces the function by a simpler local approximation and integrates that approximation exactly.', 0),
  ('94823070-2367-4a04-bd6e-d8caff58ff74', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'b0c1dfc8-eb0c-45c3-a4d8-5012e1e8c995', 'concept'::public.curated_course_node_type, 'Midpoint and trapezoidal rules', null, 0),
  ('d7292558-02e8-42b0-815d-1e90dde47526', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'b0c1dfc8-eb0c-45c3-a4d8-5012e1e8c995', 'concept'::public.curated_course_node_type, 'Simpson''s rule and its polynomial intuition', null, 1),
  ('d50c60a7-b959-4d87-a447-08778e77169e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'b0c1dfc8-eb0c-45c3-a4d8-5012e1e8c995', 'concept'::public.curated_course_node_type, 'Composite rules on equal subintervals', null, 2),
  ('9d723e31-9001-4ba6-980e-22e82467047e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'b0c1dfc8-eb0c-45c3-a4d8-5012e1e8c995', 'concept'::public.curated_course_node_type, 'Using tabulated or experimental data', null, 3),
  ('32f3047e-5c16-4cb8-babd-bd67fc0ffe4d', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'f6c87778-1292-4836-9625-49b8f156bebe', 'subtopic'::public.curated_course_node_type, 'Error bounds and refinement', 'A numerical result must be paired with evidence about its accuracy and sensitivity to step size.', 1),
  ('2a40c6ce-e899-44f6-8ef2-a9dd8cc60733', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '32f3047e-5c16-4cb8-babd-bd67fc0ffe4d', 'concept'::public.curated_course_node_type, 'Qualitative error from monotonicity and concavity', null, 0),
  ('8f6b9f14-cd30-4fca-861b-a74a978128bd', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '32f3047e-5c16-4cb8-babd-bd67fc0ffe4d', 'concept'::public.curated_course_node_type, 'Standard derivative-based error bounds', null, 1),
  ('93f20279-9a81-4833-af86-c69e19a137ec', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '32f3047e-5c16-4cb8-babd-bd67fc0ffe4d', 'concept'::public.curated_course_node_type, 'Partition refinement and observed convergence', null, 2),
  ('8cc9aab4-f274-4caa-adfa-61bb37cd02f5', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '32f3047e-5c16-4cb8-babd-bd67fc0ffe4d', 'concept'::public.curated_course_node_type, 'Absolute, relative, and percentage error', null, 3),
  ('e140332a-27a1-4fbb-a74b-c38910a8b703', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'f6c87778-1292-4836-9625-49b8f156bebe', 'subtopic'::public.curated_course_node_type, 'Computational implementation', 'A short spreadsheet or program makes the algorithm transparent and prepares students for later numerical methods.', 2),
  ('5bab6714-fb6a-404e-a902-465845c12a01', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e140332a-27a1-4fbb-a74b-c38910a8b703', 'concept'::public.curated_course_node_type, 'Constructing nodes, widths, weights, and sampled values', null, 0),
  ('aea9667d-a99e-4f4f-ad8e-5635a488e12e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e140332a-27a1-4fbb-a74b-c38910a8b703', 'concept'::public.curated_course_node_type, 'Vectorized or table-based summation', null, 1),
  ('20c5da54-2083-4538-a3fb-4c7bade1a98d', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e140332a-27a1-4fbb-a74b-c38910a8b703', 'concept'::public.curated_course_node_type, 'Comparing methods on a function with a known integral', null, 2),
  ('fd6cdb2c-b6b2-4e56-900e-6d3f23d99188', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'e140332a-27a1-4fbb-a74b-c38910a8b703', 'concept'::public.curated_course_node_type, 'Documenting inputs, assumptions, precision, and stopping decisions', null, 3),
  ('75bed346-97d8-4ae0-8064-45ec130e641e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Improper Integrals and Continuous Tails', 'Improper integrals extend accumulation to infinite intervals and unbounded integrands. Their value is defined through limits, so convergence must be established before algebraic evaluation is trusted.', 5),
  ('fafde445-457f-4fcb-92ab-0498f16693a7', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '75bed346-97d8-4ae0-8064-45ec130e641e', 'subtopic'::public.curated_course_node_type, 'Infinite intervals', 'An integral over an unbounded interval is a limit of integrals over finite intervals.', 0),
  ('02c7faef-ee7f-4ff0-844d-3915da5113e4', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'fafde445-457f-4fcb-92ab-0498f16693a7', 'concept'::public.curated_course_node_type, 'One-sided and two-sided infinite intervals', null, 0),
  ('0a7c09e0-f3ae-4c82-96bc-b79923f9ce96', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'fafde445-457f-4fcb-92ab-0498f16693a7', 'concept'::public.curated_course_node_type, 'Splitting at a finite point when both tails are infinite', null, 1),
  ('9e794a1c-ed28-4dea-ba67-0fbf2cd0ad08', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'fafde445-457f-4fcb-92ab-0498f16693a7', 'concept'::public.curated_course_node_type, 'p-integrals as benchmark examples', null, 2),
  ('38576227-61c3-4272-b1d8-cfe6e35b4f54', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'fafde445-457f-4fcb-92ab-0498f16693a7', 'concept'::public.curated_course_node_type, 'Interpreting finite total mass, probability, or exposure over an infinite horizon', null, 3),
  ('7f7a40f6-fb03-4132-b6c0-4f591c1121b1', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '75bed346-97d8-4ae0-8064-45ec130e641e', 'subtopic'::public.curated_course_node_type, 'Unbounded integrands', 'A vertical asymptote inside or at the endpoint requires a one-sided limiting definition.', 1),
  ('ac5e82cc-059a-4c2c-9fbd-fc185f9b6b0d', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '7f7a40f6-fb03-4132-b6c0-4f591c1121b1', 'concept'::public.curated_course_node_type, 'Endpoint singularities', null, 0),
  ('3e5d66a9-d351-4888-972d-c0bbe3d097fc', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '7f7a40f6-fb03-4132-b6c0-4f591c1121b1', 'concept'::public.curated_course_node_type, 'Interior singularities and mandatory interval splitting', null, 1),
  ('9106c261-ca4f-4be3-b99b-a5be1f2cbe17', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '7f7a40f6-fb03-4132-b6c0-4f591c1121b1', 'concept'::public.curated_course_node_type, 'Convergent versus divergent behavior', null, 2),
  ('da265283-9fc0-482f-a8b9-8a76365bb709', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '7f7a40f6-fb03-4132-b6c0-4f591c1121b1', 'concept'::public.curated_course_node_type, 'Avoiding cancellation across an undefined point', null, 3),
  ('d0c5a9b4-d38c-4d92-af29-946407a54be0', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '75bed346-97d8-4ae0-8064-45ec130e641e', 'subtopic'::public.curated_course_node_type, 'Comparison and estimation', 'Comparison tests transfer known convergence behavior from a benchmark integrand to a new one.', 2),
  ('33551a0f-97b9-44aa-be2c-be218e6abe2e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'd0c5a9b4-d38c-4d92-af29-946407a54be0', 'concept'::public.curated_course_node_type, 'Direct comparison for nonnegative functions', null, 0),
  ('e2feb3c2-1a63-4801-89ec-cd75afeb90bc', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'd0c5a9b4-d38c-4d92-af29-946407a54be0', 'concept'::public.curated_course_node_type, 'Limit comparison intuition', null, 1),
  ('c020f8b4-29fe-4bee-be45-3437be4012e1', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'd0c5a9b4-d38c-4d92-af29-946407a54be0', 'concept'::public.curated_course_node_type, 'Tail bounds and practical truncation error', null, 2),
  ('d5605b1a-e09c-4e67-8f76-dd314d12042c', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'd0c5a9b4-d38c-4d92-af29-946407a54be0', 'concept'::public.curated_course_node_type, 'Connections to probability distributions and long-run models', null, 3),
  ('17676324-a509-4117-b496-3403d87df33e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Applications of Integration', 'Applications of integration teach the central modeling move of Calculus II: identify a thin contribution, express it as density or rate times a small width, and sum continuously over the correct bounds.', 6),
  ('eb0aaafd-2ac4-47c5-b5e1-0a16594820b2', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '17676324-a509-4117-b496-3403d87df33e', 'subtopic'::public.curated_course_node_type, 'Area, volume, and geometry', 'The geometry of a slice determines the integrand. A sketch, orientation, and units are essential parts of the solution.', 0),
  ('3856b443-6376-4f35-9eba-d4fbd508ec35', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'eb0aaafd-2ac4-47c5-b5e1-0a16594820b2', 'concept'::public.curated_course_node_type, 'Area between curves with vertical or horizontal slices', null, 0),
  ('28be3892-cd96-4a62-8e10-866efa789086', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'eb0aaafd-2ac4-47c5-b5e1-0a16594820b2', 'concept'::public.curated_course_node_type, 'Volumes by cross-sections, disks, washers, and shells', null, 1),
  ('ff944819-0681-4d3d-aa46-88a2f2f589bd', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'eb0aaafd-2ac4-47c5-b5e1-0a16594820b2', 'concept'::public.curated_course_node_type, 'Arc length of a graph and parametric curve', null, 2),
  ('5ea9d71c-6860-4ba1-b42a-9cb77e2e074e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'eb0aaafd-2ac4-47c5-b5e1-0a16594820b2', 'concept'::public.curated_course_node_type, 'Surface area of revolution as enrichment', null, 3),
  ('fd59ecb0-ab2d-4ed1-a442-36661e7a407b', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '17676324-a509-4117-b496-3403d87df33e', 'subtopic'::public.curated_course_node_type, 'Work, force, and distributed quantities', 'When force or density varies, a definite integral combines local contributions into a total.', 1),
  ('6be49969-45c6-4ad6-bc7f-0512e2b4c9ff', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'fd59ecb0-ab2d-4ed1-a442-36661e7a407b', 'concept'::public.curated_course_node_type, 'Work by a variable force and springs', null, 0),
  ('aeddcd4d-453f-4721-b055-ebd39ee1e749', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'fd59ecb0-ab2d-4ed1-a442-36661e7a407b', 'concept'::public.curated_course_node_type, 'Pumping fluids and hydrostatic force', null, 1),
  ('6943abc3-53a2-40de-9fc6-530e3b6bcb86', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'fd59ecb0-ab2d-4ed1-a442-36661e7a407b', 'concept'::public.curated_course_node_type, 'Mass from linear density and center-of-mass ideas', null, 2),
  ('b26bace3-b0f1-4773-a4b5-b566533e3d98', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'fd59ecb0-ab2d-4ed1-a442-36661e7a407b', 'concept'::public.curated_course_node_type, 'Engineering units and physical reasonableness', null, 3),
  ('7c9ffec3-5577-4fe4-939e-b8df06e74755', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '17676324-a509-4117-b496-3403d87df33e', 'subtopic'::public.curated_course_node_type, 'Cross-disciplinary accumulation', 'The same integral structure appears in life science, chemistry, economics, and computing when a varying rate or density is accumulated.', 2),
  ('cb52e063-4921-497f-a633-b1c7cef9d886', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '7c9ffec3-5577-4fe4-939e-b8df06e74755', 'concept'::public.curated_course_node_type, 'Biological exposure, flow, and population totals', null, 0),
  ('731e9055-169f-4ac6-8d05-ab32f358f139', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '7c9ffec3-5577-4fe4-939e-b8df06e74755', 'concept'::public.curated_course_node_type, 'Chemical concentration, yield, and transport totals', null, 1),
  ('06d3f81c-2a95-453a-931a-121eb3896419', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '7c9ffec3-5577-4fe4-939e-b8df06e74755', 'concept'::public.curated_course_node_type, 'Economic surplus, discounted flows, and accumulated marginal quantities', null, 2),
  ('5e2722e6-0b42-4799-96b6-fc10667677f3', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '7c9ffec3-5577-4fe4-939e-b8df06e74755', 'concept'::public.curated_course_node_type, 'Cumulative cost or resource use from sampled performance data', null, 3),
  ('db592d3a-69cd-4beb-b9cf-a0d0d85bab4b', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'First-Order Differential Equations and Dynamic Models', 'Differential equations express systems through rates rather than explicit formulas. A focused introduction gives every degree a bridge from calculus techniques to growth, decay, equilibrium, and later modeling courses.', 7),
  ('2bdc6164-494d-4fc1-974f-aabb20fa0383', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'db592d3a-69cd-4beb-b9cf-a0d0d85bab4b', 'subtopic'::public.curated_course_node_type, 'Separable equations and initial values', 'Separation rewrites a rate law so each variable can be integrated on its own side, after which an initial condition selects one solution.', 0),
  ('0afd9c42-851c-4e60-ba7f-22aa47db52af', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2bdc6164-494d-4fc1-974f-aabb20fa0383', 'concept'::public.curated_course_node_type, 'Recognizing and separating dy/dx=g(x)h(y)', null, 0),
  ('793e015f-450f-4f03-9c9e-477001a75a1a', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2bdc6164-494d-4fc1-974f-aabb20fa0383', 'concept'::public.curated_course_node_type, 'Implicit and explicit solution forms', null, 1),
  ('76be0716-9911-483a-9af2-4378cdd22049', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2bdc6164-494d-4fc1-974f-aabb20fa0383', 'concept'::public.curated_course_node_type, 'Initial-value problems and parameter determination', null, 2),
  ('3f6a4edb-a516-4c6e-a4aa-f611c8bdd386', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2bdc6164-494d-4fc1-974f-aabb20fa0383', 'concept'::public.curated_course_node_type, 'Checking a solution in the original equation', null, 3),
  ('678ca690-6f5b-46db-9734-97714c387f59', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'db592d3a-69cd-4beb-b9cf-a0d0d85bab4b', 'subtopic'::public.curated_course_node_type, 'Growth, decay, and logistic models', 'Model shape follows from how the rate depends on the current state and its distance from equilibrium.', 1),
  ('f8b0dcc8-1587-4807-94a1-e9fcdb1fed33', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '678ca690-6f5b-46db-9734-97714c387f59', 'concept'::public.curated_course_node_type, 'Exponential growth and decay', null, 0),
  ('abcb64bc-45a0-44fc-8661-50ec0698ecc6', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '678ca690-6f5b-46db-9734-97714c387f59', 'concept'::public.curated_course_node_type, 'Half-life, doubling time, and proportional-rate interpretation', null, 1),
  ('8d5d09d6-bf45-4bdf-9cb6-5a42d6ea1200', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '678ca690-6f5b-46db-9734-97714c387f59', 'concept'::public.curated_course_node_type, 'Logistic growth, carrying capacity, and inflection', null, 2),
  ('0df952d3-e9a2-43d0-82d7-cfdd88449bd3', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '678ca690-6f5b-46db-9734-97714c387f59', 'concept'::public.curated_course_node_type, 'Model assumptions and parameter units', null, 3),
  ('859993e7-affc-40d1-9808-facaf1be6748', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'db592d3a-69cd-4beb-b9cf-a0d0d85bab4b', 'subtopic'::public.curated_course_node_type, 'Qualitative and numerical behavior', 'Exact formulas are only one way to understand a differential equation; slope fields and numerical steps reveal direction and stability.', 2),
  ('0abd4f35-7eb5-44d4-9f7e-7a887d0b8a30', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '859993e7-affc-40d1-9808-facaf1be6748', 'concept'::public.curated_course_node_type, 'Direction fields and solution curves', null, 0),
  ('57da6ba2-f3f5-47b0-99d1-c769cff804dc', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '859993e7-affc-40d1-9808-facaf1be6748', 'concept'::public.curated_course_node_type, 'Equilibria and qualitative stability', null, 1),
  ('801d9566-8642-45d4-950f-a84f466f8214', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '859993e7-affc-40d1-9808-facaf1be6748', 'concept'::public.curated_course_node_type, 'Euler''s method as a first numerical solver', null, 2),
  ('c2059e61-4ddd-4788-8ca2-7745b8ee5015', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '859993e7-affc-40d1-9808-facaf1be6748', 'concept'::public.curated_course_node_type, 'Comparing exact, numerical, and graphical solutions', null, 3),
  ('02eb2bdc-ef7f-45d7-a1da-18d393034f7f', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Sequences and the Meaning of Infinite Processes', 'Sequences formalize ordered approximation and long-run behavior. They provide the language needed to define an infinite series and to reason carefully about convergence rather than treating infinity as a number.', 8),
  ('9f13b8bd-adab-46cd-9b4b-7b27b1f6f36a', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '02eb2bdc-ef7f-45d7-a1da-18d393034f7f', 'subtopic'::public.curated_course_node_type, 'Sequence definitions and representations', 'A sequence can be explicit, recursive, graphical, or generated by an algorithm, and each representation reveals different structure.', 0),
  ('ab825592-3110-40b3-b71b-61ddb7cabaec', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '9f13b8bd-adab-46cd-9b4b-7b27b1f6f36a', 'concept'::public.curated_course_node_type, 'Terms, indices, explicit formulas, and recurrence relations', null, 0),
  ('70b9d87b-9784-40c9-920d-c848d3d07bde', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '9f13b8bd-adab-46cd-9b4b-7b27b1f6f36a', 'concept'::public.curated_course_node_type, 'Graphs and tables of sequence values', null, 1),
  ('fdadfb63-f2b1-4458-9138-f60b83e6e809', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '9f13b8bd-adab-46cd-9b4b-7b27b1f6f36a', 'concept'::public.curated_course_node_type, 'Monotone and bounded behavior', null, 2),
  ('bd6e9aaa-9ccb-42a1-9b75-8703b3880f6d', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '9f13b8bd-adab-46cd-9b4b-7b27b1f6f36a', 'concept'::public.curated_course_node_type, 'Arithmetic, geometric, factorial, and recursively defined examples', null, 3),
  ('5aa6d890-12f0-4c69-86e6-254acee0d7d1', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '02eb2bdc-ef7f-45d7-a1da-18d393034f7f', 'subtopic'::public.curated_course_node_type, 'Limits of sequences', 'Convergence means terms can be made arbitrarily close to a finite value by going far enough in the sequence.', 1),
  ('69900832-4589-43d3-9b2a-cc6f59b1af1b', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '5aa6d890-12f0-4c69-86e6-254acee0d7d1', 'concept'::public.curated_course_node_type, 'Limit laws for sequences', null, 0),
  ('727109a6-f81b-4a70-a1c3-1043f604d823', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '5aa6d890-12f0-4c69-86e6-254acee0d7d1', 'concept'::public.curated_course_node_type, 'Dominant growth and algebraic simplification', null, 1),
