  ('5b9ebf09-07be-4052-9c1b-24a487ed8c80', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '5aa6d890-12f0-4c69-86e6-254acee0d7d1', 'concept'::public.curated_course_node_type, 'Monotone Convergence Theorem at an intuitive, hypothesis-aware level', null, 3),
  ('d9b0dc74-d5a8-495a-a432-ff231f70f1d5', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '02eb2bdc-ef7f-45d7-a1da-18d393034f7f', 'subtopic'::public.curated_course_node_type, 'Recursive approximation and iteration', 'Many algorithms produce sequences whose convergence determines whether the computation succeeds.', 2),
  ('4c526110-81fc-4dfa-9a38-2227e22f8e3f', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'd9b0dc74-d5a8-495a-a432-ff231f70f1d5', 'concept'::public.curated_course_node_type, 'Newton iterations revisited', null, 0),
