  ('24b4363d-4d2c-4cae-82d1-08f0d3987315', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'd9b0dc74-d5a8-495a-a432-ff231f70f1d5', 'concept'::public.curated_course_node_type, 'Numerical stabilization and stopping rules', null, 2),
  ('59a2f53a-e1eb-46c1-a8f1-806d65375abb', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'd9b0dc74-d5a8-495a-a432-ff231f70f1d5', 'concept'::public.curated_course_node_type, 'Examples from population, finance, and computational methods', null, 3),
  ('02b4b3d4-2606-48f5-a023-21a6bbcb3639', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Infinite Series and Convergence Tests', 'An infinite series is the limit of its partial sums. Calculus II develops a toolkit for deciding whether that limit exists, estimating the remainder, and choosing a test based on structure.', 9),
  ('87ea2004-46bb-4c84-a498-613d00ca6ddf', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '02b4b3d4-2606-48f5-a023-21a6bbcb3639', 'subtopic'::public.curated_course_node_type, 'Series foundations', 'The sequence of partial sums—not the individual terms—determines whether an infinite sum converges.', 0),
  ('a3e5bab7-cbd6-4f68-8695-66a9e74261aa', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '87ea2004-46bb-4c84-a498-613d00ca6ddf', 'concept'::public.curated_course_node_type, 'Partial sums and the definition of convergence', null, 0),
  ('f5481992-2f8b-497c-96ba-09ab0f161972', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '87ea2004-46bb-4c84-a498-613d00ca6ddf', 'concept'::public.curated_course_node_type, 'Geometric and telescoping series', null, 1),
  ('df7ae349-83ab-4849-b23b-0e8541bda839', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '87ea2004-46bb-4c84-a498-613d00ca6ddf', 'concept'::public.curated_course_node_type, 'The nth-term divergence test', null, 2),
  ('aa6e6454-ea8e-479a-aad7-68300a1ca47c', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '87ea2004-46bb-4c84-a498-613d00ca6ddf', 'concept'::public.curated_course_node_type, 'Linearity and basic algebra of convergent series', null, 3),
  ('29d16137-86a4-46c0-a469-db127d0c7893', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '02b4b3d4-2606-48f5-a023-21a6bbcb3639', 'subtopic'::public.curated_course_node_type, 'Positive-term tests', 'Positive series can often be compared with benchmark sums or integrals whose convergence is already understood.', 1),
  ('b393ee33-c4e3-47c5-9480-56e047f2c72a', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '29d16137-86a4-46c0-a469-db127d0c7893', 'concept'::public.curated_course_node_type, 'Integral Test and p-series', null, 0),
  ('635686a9-f822-4d99-aaf5-72a4c71ad1ea', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '29d16137-86a4-46c0-a469-db127d0c7893', 'concept'::public.curated_course_node_type, 'Direct and limit comparison tests', null, 1),
  ('a956fdb7-70cd-4192-85a7-094ef5d1ce03', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '29d16137-86a4-46c0-a469-db127d0c7893', 'concept'::public.curated_course_node_type, 'Ratio Test and Root Test', null, 2),
  ('735b32b8-2f0e-4a77-9d7b-d6ee7250acb1', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '29d16137-86a4-46c0-a469-db127d0c7893', 'concept'::public.curated_course_node_type, 'Choosing an efficient test from the form of the terms', null, 3),
  ('ec153cf4-cb06-4c8f-9b96-b6c988ae42b2', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '02b4b3d4-2606-48f5-a023-21a6bbcb3639', 'subtopic'::public.curated_course_node_type, 'Alternation, absolute convergence, and error', 'Signs can create cancellation, but absolute convergence gives stronger stability under rearrangement and manipulation.', 2),
  ('6355d706-ff8d-4209-8a60-de7f8fc851ee', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'ec153cf4-cb06-4c8f-9b96-b6c988ae42b2', 'concept'::public.curated_course_node_type, 'Alternating Series Test', null, 0),
  ('e406f240-4e83-4820-992f-3a49fb0f8f3d', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'ec153cf4-cb06-4c8f-9b96-b6c988ae42b2', 'concept'::public.curated_course_node_type, 'Absolute versus conditional convergence', null, 1),
  ('6d64ef06-38c2-485f-bf0a-5bddd4be63d3', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'ec153cf4-cb06-4c8f-9b96-b6c988ae42b2', 'concept'::public.curated_course_node_type, 'Alternating-series remainder estimate', null, 2),
  ('609c0a61-a78c-48fc-ac0e-2e0955930061', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'ec153cf4-cb06-4c8f-9b96-b6c988ae42b2', 'concept'::public.curated_course_node_type, 'Tail estimation and reporting the number of terms required', null, 3),
  ('dc258c08-70d4-47e2-bf8e-1ec4a29f2d99', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Power Series and Interval of Convergence', 'A power series is an infinite polynomial centered at a point. Within its interval of convergence it can represent, differentiate, integrate, and approximate functions using familiar algebraic operations.', 10),
  ('08bcbc6a-552a-47e0-8144-afbc41dca27e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'dc258c08-70d4-47e2-bf8e-1ec4a29f2d99', 'subtopic'::public.curated_course_node_type, 'Power-series structure', 'The center and radius determine where a power series behaves like a function and where it fails to converge.', 0),
  ('2dd0cfc6-b9e1-497a-9f8f-75ee791408b0', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '08bcbc6a-552a-47e0-8144-afbc41dca27e', 'concept'::public.curated_course_node_type, 'General form centered at a', null, 0),
  ('297500b3-ecb1-4111-b169-ce7390a25591', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '08bcbc6a-552a-47e0-8144-afbc41dca27e', 'concept'::public.curated_course_node_type, 'Radius and interval of convergence', null, 1),
  ('4f36a85a-a644-440a-9fd0-814119d76302', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '08bcbc6a-552a-47e0-8144-afbc41dca27e', 'concept'::public.curated_course_node_type, 'Ratio or Root Test for the radius', null, 2),
  ('3b71b2f7-74da-4c38-b9b1-964d24d40f21', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '08bcbc6a-552a-47e0-8144-afbc41dca27e', 'concept'::public.curated_course_node_type, 'Separate endpoint testing', null, 3),
  ('22c9e348-754c-4807-9e55-fbb9aea46766', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'dc258c08-70d4-47e2-bf8e-1ec4a29f2d99', 'subtopic'::public.curated_course_node_type, 'Building new series', 'Known geometric-series identities generate many useful expansions through algebra, substitution, differentiation, and integration.', 1),
  ('97042467-193c-4164-9f0c-395ae65c261f', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '22c9e348-754c-4807-9e55-fbb9aea46766', 'concept'::public.curated_course_node_type, 'Geometric-series template', null, 0),
  ('09b0bbec-c7ad-4b88-88cf-eabd1e723ab0', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '22c9e348-754c-4807-9e55-fbb9aea46766', 'concept'::public.curated_course_node_type, 'Substitution and rescaling', null, 1),
  ('ae454964-7943-46bc-9853-b9ee60e6dfc1', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '22c9e348-754c-4807-9e55-fbb9aea46766', 'concept'::public.curated_course_node_type, 'Term-by-term differentiation and integration', null, 2),
  ('4ba7c4e1-ef0a-4519-a385-5d82cf6a9c12', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '22c9e348-754c-4807-9e55-fbb9aea46766', 'concept'::public.curated_course_node_type, 'Products and simple combinations of series', null, 3),
  ('921b588e-7744-4c5b-ac06-3c93643a4b8a', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'dc258c08-70d4-47e2-bf8e-1ec4a29f2d99', 'subtopic'::public.curated_course_node_type, 'Functions defined by series', 'A power series is both a computational object and a function with a domain determined by convergence.', 2),
  ('67706307-2285-406a-83f4-f67dfda2f9ca', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '921b588e-7744-4c5b-ac06-3c93643a4b8a', 'concept'::public.curated_course_node_type, 'Evaluating and graphing partial-sum approximations', null, 0),
  ('cc256d55-37bd-4318-94dd-6c2b1d5c2c17', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '921b588e-7744-4c5b-ac06-3c93643a4b8a', 'concept'::public.curated_course_node_type, 'Differentiability and integrability inside the radius', null, 1),
  ('4a007b2b-c24f-4f69-9d99-884333e85440', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '921b588e-7744-4c5b-ac06-3c93643a4b8a', 'concept'::public.curated_course_node_type, 'Coefficient matching in simple models', null, 2),
  ('f7c68a25-ba10-4784-97b9-6109e72f9f71', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '921b588e-7744-4c5b-ac06-3c93643a4b8a', 'concept'::public.curated_course_node_type, 'Error observed through successive partial sums', null, 3),
  ('f869f35b-6553-49e3-9a1e-cc3092820908', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Taylor Series, Approximation, and Remainder', 'Taylor polynomials encode a function''s derivatives at one point into a polynomial approximation. The remainder term makes approximation quality analyzable rather than merely visual.', 11),
  ('2fb5950d-74b3-4c6a-81cf-e975e1bdaf1a', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'f869f35b-6553-49e3-9a1e-cc3092820908', 'subtopic'::public.curated_course_node_type, 'Taylor and Maclaurin polynomials', 'Matching derivatives at the center creates the locally best polynomial of a chosen degree.', 0),
  ('3e5aca7a-3506-4836-9a26-bc1cc218e23e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2fb5950d-74b3-4c6a-81cf-e975e1bdaf1a', 'concept'::public.curated_course_node_type, 'Constructing coefficients from derivatives', null, 0),
  ('c8c5b4f7-9926-45cc-9605-47561920b4eb', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2fb5950d-74b3-4c6a-81cf-e975e1bdaf1a', 'concept'::public.curated_course_node_type, 'Maclaurin series for exp, sine, cosine, and geometric-derived functions', null, 1),
  ('9e5bf526-7404-4021-856c-9bf14588d5b9', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2fb5950d-74b3-4c6a-81cf-e975e1bdaf1a', 'concept'::public.curated_course_node_type, 'Centering at a nonzero point', null, 2),
  ('bdf9c121-be4f-4279-a171-002be487af70', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '2fb5950d-74b3-4c6a-81cf-e975e1bdaf1a', 'concept'::public.curated_course_node_type, 'Reading local behavior from coefficients', null, 3),
  ('70ab3074-fc09-488d-b316-47566bf1a161', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'f869f35b-6553-49e3-9a1e-cc3092820908', 'subtopic'::public.curated_course_node_type, 'Convergence to the function', 'A Taylor series can converge as a series yet fail to equal the original function; the remainder resolves that distinction.', 1),
  ('51a5405a-88b8-420f-845d-5fbb5534eeac', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '70ab3074-fc09-488d-b316-47566bf1a161', 'concept'::public.curated_course_node_type, 'Taylor''s Theorem with remainder', null, 0),
  ('fa3ebecc-574f-443d-b99d-e7e83cdd23be', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '70ab3074-fc09-488d-b316-47566bf1a161', 'concept'::public.curated_course_node_type, 'Lagrange remainder bound', null, 1),
  ('73625cfd-f1f3-46b4-bd4b-81a834508700', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '70ab3074-fc09-488d-b316-47566bf1a161', 'concept'::public.curated_course_node_type, 'Intervals on which the remainder tends to zero', null, 2),
  ('bda9ad07-100c-415d-ad4e-47f910f7469a', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '70ab3074-fc09-488d-b316-47566bf1a161', 'concept'::public.curated_course_node_type, 'Alternating-series error when applicable', null, 3),
  ('597f19ed-3e2e-40ed-8214-0819c1d3c82e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', 'f869f35b-6553-49e3-9a1e-cc3092820908', 'subtopic'::public.curated_course_node_type, 'Applications of approximation', 'Series make hard functions and integrals accessible to hand calculation and computation.', 2),
  ('12e25f0f-5745-4552-ae5a-dd7b21424a87', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '597f19ed-3e2e-40ed-8214-0819c1d3c82e', 'concept'::public.curated_course_node_type, 'Approximating function values with controlled error', null, 0),
  ('dd56eb0d-fd59-400d-99d9-5d2e7747186e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '597f19ed-3e2e-40ed-8214-0819c1d3c82e', 'concept'::public.curated_course_node_type, 'Evaluating non-elementary definite integrals by series', null, 1),
  ('7b6ed7ef-2a53-4ad3-a615-6b9e34b1568d', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '597f19ed-3e2e-40ed-8214-0819c1d3c82e', 'concept'::public.curated_course_node_type, 'Approximating solutions of differential equations as enrichment', null, 2),
  ('daa968f3-19c7-4b32-a476-7d1425fac558', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '597f19ed-3e2e-40ed-8214-0819c1d3c82e', 'concept'::public.curated_course_node_type, 'Comparing Taylor, numerical quadrature, and calculator values', null, 3),
  ('3412eb2d-f098-4eb0-a403-d7de65cae509', '58330bf3-36de-40d0-821f-4669ed1cbe1f', null, 'topic'::public.curated_course_node_type, 'Parametric Curves, Polar Coordinates, and Vector Bridge', 'Alternative coordinate descriptions let calculus analyze curves that are awkward or impossible to express as y=f(x). This closing unit also provides a deliberate bridge to multivariable calculus and vector-based applications.', 12),
  ('881939c0-c609-4732-b279-76f5b4428d2e', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '3412eb2d-f098-4eb0-a403-d7de65cae509', 'subtopic'::public.curated_course_node_type, 'Parametric curves', 'A parameter records how both coordinates evolve, naturally representing motion, loops, and multi-valued curves.', 0),
  ('9a82b4b8-dbdc-4c13-8adb-da46dbf79b83', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '881939c0-c609-4732-b279-76f5b4428d2e', 'concept'::public.curated_course_node_type, 'Eliminating a parameter and choosing orientation', null, 0),
  ('35b6136a-2708-46d1-8053-0e06e5e95dfc', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '881939c0-c609-4732-b279-76f5b4428d2e', 'concept'::public.curated_course_node_type, 'First and second derivatives with respect to the parameter', null, 1),
  ('a0720fed-3fb0-41ba-b6fd-70f92d688bed', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '881939c0-c609-4732-b279-76f5b4428d2e', 'concept'::public.curated_course_node_type, 'Parametric arc length and speed', null, 2),
  ('a9e5591e-4dab-4040-bb7e-bf146291644b', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '881939c0-c609-4732-b279-76f5b4428d2e', 'concept'::public.curated_course_node_type, 'Applications to trajectories and mechanisms', null, 3),
  ('69fde6aa-98f0-41ed-a4fe-cd8e4c855899', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '3412eb2d-f098-4eb0-a403-d7de65cae509', 'subtopic'::public.curated_course_node_type, 'Polar coordinates and polar curves', 'Polar coordinates describe a point by distance and angle, making rotational symmetry and many physical shapes natural.', 1),
  ('701893e4-c637-4109-a471-77cde046b909', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '69fde6aa-98f0-41ed-a4fe-cd8e4c855899', 'concept'::public.curated_course_node_type, 'Converting between Cartesian and polar forms', null, 0),
  ('4a357425-baaf-407b-ab00-49ed2c5d5183', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '69fde6aa-98f0-41ed-a4fe-cd8e4c855899', 'concept'::public.curated_course_node_type, 'Graphing lines, circles, spirals, roses, and limacons', null, 1),
  ('4da88d77-deae-4e91-8c01-c9d193c992b3', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '69fde6aa-98f0-41ed-a4fe-cd8e4c855899', 'concept'::public.curated_course_node_type, 'Slope, area, and arc length in polar form', null, 2),
  ('c39858ff-39ba-40d0-a9ae-7e0d692303ec', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '69fde6aa-98f0-41ed-a4fe-cd8e4c855899', 'concept'::public.curated_course_node_type, 'Finding intersections and avoiding duplicate tracing', null, 3),
  ('9945be6f-3141-48f4-a485-c9c6575603f6', '58330bf3-36de-40d0-821f-4669ed1cbe1f', '3412eb2d-f098-4eb0-a403-d7de65cae509', 'subtopic'::public.curated_course_node_type, 'Vectors and multivariable readiness', 'A concise vector preview links parametric motion to later work with space, fields, forces, gradients, and systems.', 2),
