insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'textbook'::public.curated_course_resource_kind, 'OpenStax Calculus Volume 2', 'https://openstax.org/details/books/calculus-volume-2', 'Best default open textbook for integration techniques, differential equations, sequences and series, parametric equations, and polar coordinates.', 0),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'textbook'::public.curated_course_resource_kind, 'Calculus: Early Transcendentals', 'Cengage', 'James Stewart. Large problem bank and standard engineering/science sequence for integration and series.', 1),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'textbook'::public.curated_course_resource_kind, 'Thomas'' Calculus', 'Pearson', 'Reliable reference with clear examples across techniques, applications, series, parametric curves, and polar coordinates.', 2),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'textbook'::public.curated_course_resource_kind, 'Calculus: Single Variable', 'Wiley', 'Hughes-Hallett et al. Strong for conceptual questions, modeling, data, and multiple representations.', 3),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'textbook'::public.curated_course_resource_kind, 'The Calculus Lifesaver', 'Princeton University Press', 'Adrian Banner. Readable supplemental explanations and problem-solving guidance, especially useful for independent review.', 4),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'textbook'::public.curated_course_resource_kind, 'Calculus (Spivak)', 'Publish or Perish', 'Michael Spivak. Optional proof-enrichment for mathematics majors and advanced students; use selectively for rigorous exercises.', 5),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'website'::public.curated_course_resource_kind, 'MIT OpenCourseWare 18.01SC Single Variable Calculus', 'https://ocw.mit.edu/courses/18-01sc-single-variable-calculus-fall-2010/', 'Challenging lectures, notes, problem sets, solutions, and exams covering integration techniques, improper integrals, series, Taylor series, parametric equations, and polar coordinates.', 6),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'website'::public.curated_course_resource_kind, 'MIT Calculus Open Textbook', 'https://ocw.mit.edu/courses/res-18-001-calculus-fall-2023/', 'Current open reference and study guide with numerical integration, techniques, applications, polar coordinates, series, and vectors.', 7),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'website'::public.curated_course_resource_kind, 'Paul''s Online Math Notes - Calculus II', 'https://tutorial.math.lamar.edu/Classes/CalcII/CalcII.aspx', 'Concise notes and many worked problems for techniques and convergence tests.', 8),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'website'::public.curated_course_resource_kind, 'Khan Academy AP/College Calculus BC', 'https://www.khanacademy.org/math/ap-calculus-bc', 'Guided practice for integration applications, differential equations, parametric/polar topics, and series.', 9),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'website'::public.curated_course_resource_kind, 'Princeton MAT104 sample questions', 'https://web.math.princeton.edu/~nelson/104/samples.html', 'Strong calculator-free practice emphasizing sophisticated pattern recognition and adaptive technique choice.', 10),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'website'::public.curated_course_resource_kind, 'Desmos Graphing Calculator', 'https://www.desmos.com/calculator', 'Visualize parametric/polar curves, partial sums, and model behavior.', 11),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'website'::public.curated_course_resource_kind, 'GeoGebra Graphing Calculator', 'https://www.geogebra.org/graphing', 'Interactive graphing for parametric/polar curves, partial sums, and model behavior.', 12),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'website'::public.curated_course_resource_kind, 'Jupyter', 'https://jupyter.org/', 'Implement quadrature, Euler''s method, partial sums, Taylor approximations, and error comparisons with transparent, reproducible steps.', 13),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'youtube'::public.curated_course_resource_kind, 'Professor Leonard', 'https://www.youtube.com/@ProfessorLeonard', 'Long-form Calculus II lectures with detailed worked examples.', 14),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'youtube'::public.curated_course_resource_kind, '3Blue1Brown', 'https://www.youtube.com/@3blue1brown', 'Essence of Calculus: visual intuition for integration, differential equations, and approximation; use alongside rigorous exercises.', 15),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'youtube'::public.curated_course_resource_kind, 'MIT OpenCourseWare', 'https://www.youtube.com/@mitocw', 'Lecture and problem-solving videos aligned with university calculus.', 16),
  ('58330bf3-36de-40d0-821f-4669ed1cbe1f', 'youtube'::public.curated_course_resource_kind, 'The Organic Chemistry Tutor', 'https://www.youtube.com/@TheOrganicChemistryTutor', 'Focused walkthroughs for integration techniques and series practice.', 17);
